let studioVersion='',layoutPreviewTimer,layoutPreviewGeneration=0;
function renderStudio(snapshot){$('#refine-send').disabled=snapshot.busy||Boolean(snapshot.proposal)||!snapshot.fields?.length;$('#practice-start').disabled=snapshot.busy;$('#practice-finish').disabled=snapshot.busy||!snapshot.practice?.startedAt||Boolean(snapshot.practice?.stoppedAt);const signature=JSON.stringify([snapshot.jobId,snapshot.version,snapshot.practice,snapshot.fieldQuestion]);if(signature===studioVersion)return;studioVersion=signature;const fields=snapshot.fields||[];
 const old=$('#refine-field').value;$('#refine-field').replaceChildren(...fields.map(f=>new Option(f.label+' · '+f.translated,f.id)));if(fields.some(f=>f.id===old))$('#refine-field').value=old;if(snapshot.fieldQuestion)$('#refine-field').value=snapshot.fieldQuestion;
 $('#sync-lines').replaceChildren(...(inspectResult?.text||'').split('\n').filter(Boolean).map(line=>{const matches=fields.filter(f=>f.translated&&line.includes(f.translated));if(!matches.length)return element('p',line,'unmapped-line');const row=element('div','','sync-line');for(const f of matches){const b=element('button',line,'sync-line-button');b.onclick=()=>{document.querySelectorAll('.sync-line-button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');focusField(f);$('#inspect-original').scrollIntoView({block:'center',behavior:'smooth'});};row.append(b);}return row;}));
 const p=snapshot.practice;$('#practice-status').textContent=p?.startedAt?(p.stoppedAt?'Abgeschlossen · '+Math.round((p.stoppedAt-p.startedAt)/1000)+' Sekunden':'Prüfzeit läuft seit '+new Date(p.startedAt).toLocaleTimeString('de-AT')):'Noch kein Praxistest für diesen Auftrag.';if(p?.stoppedAt){$('#practice-minutes').value=p.manualMinutes;$('#practice-rating').value=p.rating;$('#practice-notes').value=p.notes||'';}
}
async function jumpToTranslatedField(field){if(!pdfDocument)return;const doc=pdfDocument,version=reviewData.version;for(let pageIndex=1;pageIndex<=Math.min(workflowSnapshot.preflight?.translationPages||1,150);pageIndex++){const page=await doc.getPage(pageIndex),content=await page.getTextContent();const matches=content.items.filter(item=>item.str?.includes(field.translated));if(matches.length){if(version!==reviewData.version||doc!==pdfDocument)return;pdfPageIndex=pageIndex;await renderReviewPDFPage();const canvas=$('#review-page-canvas canvas');if(canvas){const base=page.getViewport({scale:1}),viewport=page.getViewport({scale:canvas.width/base.width}),ctx=canvas.getContext('2d');ctx.save();for(const item of matches){const [x,y]=viewport.convertToViewportPoint(item.transform[4],item.transform[5]);const height=Math.max(item.height*viewport.scale,12),width=item.width*viewport.scale;ctx.fillStyle='rgba(20,20,20,.12)';ctx.strokeStyle='#141414';ctx.lineWidth=2;ctx.fillRect(x-3,y-height,width+6,height+5);ctx.strokeRect(x-3,y-height,width+6,height+5);}ctx.restore();}$('#inspect-translation').textContent=inspectResult.text.split('\n').filter(l=>l.includes(field.translated)).join('\n');return;}}}
function setReviewPane(pane){const view=$('#review-view');view.dataset.mobilePane=pane;$('#review-source-tab').setAttribute('aria-pressed',String(pane==='source'));$('#review-output-tab').setAttribute('aria-pressed',String(pane==='output'));if(pane==='output'&&pdfDocument)void renderReviewPDFPage();}
$('#review-source-tab').onclick=()=>setReviewPane('source');$('#review-output-tab').onclick=()=>setReviewPane('output');
$('#refine-send').onclick=()=>void inspectorTask(()=>localRequest(`/api/jobs/${reviewJobId}/refine`,{version:reviewData.version,requestId:crypto.randomUUID(),fieldId:$('#refine-field').value,notes:$('#refine-notes').value}));
$('#practice-start').onclick=()=>void inspectorTask(()=>localRequest(`/api/jobs/${reviewJobId}/practice`,{version:reviewData.version,action:'start'}));
$('#practice-finish').onclick=()=>void inspectorTask(()=>localRequest(`/api/jobs/${reviewJobId}/practice`,{version:reviewData.version,action:'finish',manualMinutes:Number($('#practice-minutes').value),rating:Number($('#practice-rating').value),notes:$('#practice-notes').value}));
$('#practice-export').onclick=()=>void inspectorTask(async()=>{const data=await localRequest('/api/practice/report').then(r=>r.json());downloadBlob(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),'translateocr-praxistest-anonym.json');});

const baseFocusField=focusField;focusField=function(field){baseFocusField(field);document.querySelectorAll('.field-check').forEach(row=>row.classList.toggle('selected-field',row.querySelector('[data-check-id]')?.dataset.checkId===field.id));void jumpToTranslatedField(field).catch(()=>{});};

let orderedFile=null,orderedPages=[];
function renderPageOrder(){const host=$('#pdf-order-pages');host.replaceChildren(...orderedPages.map((page,i)=>{const row=element('div','','pdf-order-row');row.append(element('span','Originalseite '+page));for(const [delta,label]of [[-1,'↑'],[1,'↓']]){const b=element('button',label,'secondary');b.setAttribute('aria-label','Originalseite '+page+(delta<0?' nach oben':' nach unten'));b.disabled=i+delta<0||i+delta>=orderedPages.length;b.onclick=()=>{[orderedPages[i],orderedPages[i+delta]]=[orderedPages[i+delta],orderedPages[i]];fileCorrections.set(orderedFile,{...(fileCorrections.get(orderedFile)||{}),pageOrder:[...orderedPages]});renderPageOrder();$('#pdf-order-note').textContent='Reihenfolge für die Arbeitskopie vorgemerkt. Originalanhang bleibt unverändert. Mit „Arbeitskopie ansehen“ prüfen.';};row.append(b);}return row;}));}
async function loadPageOrder(){const selected=files[Number($('#pdf-order-file').value)];if(!selected)throw new Error('Bitte PDF auswählen.');const response=await localRequest('/api/scan',{files:await documentsForRequest([selected])}).then(r=>r.json());if(!files.includes(selected))throw new Error('Dateiauswahl wurde inzwischen geändert.');orderedFile=selected;const count=response.files[0].pages;orderedPages=fileCorrections.get(selected)?.pageOrder||Array.from({length:count},(_,i)=>i+1);renderPageOrder();$('#pdf-order-note').textContent='Jede Seite bleibt erhalten. Die Pfeile ändern nur die Arbeitskopie für die Übersetzung.';}
$('#pdf-order-open').onclick=()=>void workspaceTask(async()=>{const pdfs=files.map((f,i)=>({f,i})).filter(x=>/\.pdf$/i.test(x.f.name));if(!pdfs.length)throw new Error('Bitte zuerst eine PDF auswählen.');$('#pdf-order-file').hidden=false;$('#pdf-order-file').replaceChildren(...pdfs.map(x=>new Option(x.f.name,x.i)));await loadPageOrder();});
$('#pdf-order-file').onchange=()=>void workspaceTask(loadPageOrder);
